insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].intro', 'Diriwayatkan oleh Abu Ubaid:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'Aku menghadiri solat Hari Raya bersama Umar, lalu dia memulakan solat sebelum khutbah, kemudian berkata: Sesungguhnya Rasulullah SAW melarang puasa pada dua hari ini. Adapun Hari Raya Aidiladha, kamu makan daging korban kamu; adapun Hari Raya Aidilfitri, ia adalah hari kamu berbuka daripada puasa kamu.');
