insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].quote', 'Dua hari puasa diharamkan: puasa pada Hari Raya Aidilfitri dan Hari Raya Aidiladha.');
