insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[1].cites[0].intro', 'Abu Qatadah RA meriwayatkan bahawa Rasulullah SAW bersabda:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[1].cites[0].quote', 'Aku memohon kepada Allah agar puasa pada Hari Arafah dapat menghapuskan dosa-dosa setahun yang lalu dan setahun yang akan datang, dan aku memohon kepada Allah agar puasa pada Hari Asyura dapat menghapuskan dosa-dosa setahun yang lalu.');
