insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[2].cites[0].intro', 'Salah seorang isteri Nabi Muhammad SAW berkata:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[2].cites[0].quote', 'Rasulullah Muhammad SAW biasa berpuasa pada sembilan hari pertama Zulhijjah, Hari Asyura, dan tiga hari dalam setiap bulan.');
