insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].hadith', '2417');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].hadith', '2437');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[2].id', 'fasting-reason-first-9-dhu-al-hijjah');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[2].title', 'Sembilan Hari Pertama Zulhijjah');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[1].intro', 'Diriwayatkan oleh Abdullah bin Amr bin al-As RA:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'Cukuplah bagi kamu berpuasa tiga hari dalam sebulan, kerana setiap kebaikan digandakan sepuluh kali, maka ia seperti puasa sepanjang tahun.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].hadith', '1975');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[2].intro', 'Abu Qatadah RA meriwayatkan bahawa Rasulullah SAW bersabda:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'Puasa tiga hari setiap bulan dan puasa Ramadan setiap tahun adalah puasa sepanjang masa.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].hadith', '1162');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[3].intro', 'Rasulullah SAW bersabda kepada Abu Zar:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[3].quote', 'Puasa tiga hari setiap bulan adalah seperti puasa sepanjang hayat.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].collection', 'ibnmajah');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].hadith', '1708');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[4].intro', 'Diriwayatkan daripada Jarir bin Abdullah RA bahawa Nabi SAW bersabda:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'Puasa tiga hari setiap bulan adalah puasa sepanjang hayat, dan hari-hari putih ialah hari ketiga belas, keempat belas, dan kelima belas.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].hadith', '2420');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[5].intro', 'Diriwayatkan oleh Abu Hurairah RA:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'Kekasihku, Nabi Muhammad SAW, telah berwasiat kepadaku dengan tiga perkara: berpuasa tiga hari dalam setiap bulan, solat Dhuha dua rakaat, dan solat Witir sebelum tidur.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].hadith', '1981');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[6].intro', 'Abu al-Darda RA berkata:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'Kekasihku, Nabi SAW, berpesan kepadaku dengan tiga amalan yang tidak akan aku tinggalkan kerana sesuatu apa pun: baginda berpesan kepadaku agar berpuasa tiga hari setiap bulan.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].hadith', '1433');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[0].intro', 'Nabi Muhammad SAW menasihati Abu Zar RA:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'Jika engkau berpuasa pada mana-mana hari dalam sebulan, maka berpuasalah pada hari ketiga belas, keempat belas, dan kelima belas.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].hadith', '761');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].id', 'fasting-reason-white-days');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[3].title', 'Hari-hari Putih');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'Usamah bin Zaid RA meriwayatkan bahawa Rasulullah SAW bersabda:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'Itulah dua hari amalan-amalan dibentangkan kepada Tuhan sekalian alam, dan aku suka amalanku dibentangkan ketika aku berpuasa.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].hadith', '2358');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[2].intro', 'Nabi SAW ditanya oleh Abu Qatadah al-Ansari RA tentang puasa pada hari Isnin, lalu baginda bersabda:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[2].quote', 'Ia adalah hari aku dilahirkan, dan pada hari itu aku diutuskan sebagai nabi, atau wahyu diturunkan kepadaku.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].hadith', '1162b');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[3].intro', 'Aisyah RA berkata:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[3].quote', 'Nabi SAW biasa bersungguh-sungguh berpuasa pada hari Isnin dan Khamis.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].hadith', '745');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[0].intro', 'Kenyataan khusus ini diriwayatkan oleh Abu Hurairah RA:');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[0].quote', 'Amalan-amalan dibentangkan pada hari Isnin dan Khamis, maka aku suka amalanku dibentangkan ketika aku berpuasa.');
insert into i18n_bundles (locale, code, value) values ('ms', 'fasting.reason-groups.voluntary.reasons[4].cites[0].references[1].collection', 'riyadussalihin');
